CREATE TABLE "Theme" (
 "id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL,
 "isSystem" BOOLEAN NOT NULL DEFAULT true,
 "background" JSONB NOT NULL, "typography" JSONB NOT NULL, "buttons" JSONB NOT NULL, "cards" JSONB NOT NULL,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL
);
CREATE UNIQUE INDEX "Theme_slug_key" ON "Theme"("slug");
CREATE TABLE "PageTemplate" (
 "key" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "description" TEXT NOT NULL,
 "themeKey" TEXT NOT NULL, "blocks" JSONB NOT NULL,
 CONSTRAINT "PageTemplate_themeKey_fkey" FOREIGN KEY ("themeKey") REFERENCES "Theme"("slug") ON DELETE RESTRICT ON UPDATE CASCADE
);
