ALTER TABLE "Page" ADD COLUMN "appearanceOverrides" JSONB NOT NULL DEFAULT '{}';
ALTER TABLE "Page" ADD CONSTRAINT "Page_themeKey_fkey" FOREIGN KEY ("themeKey") REFERENCES "Theme"("slug") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TYPE "SocialPlatform" AS ENUM ('INSTAGRAM','YOUTUBE','X','LINKEDIN','FACEBOOK','TIKTOK','GITHUB','DISCORD','TWITCH','SPOTIFY');
CREATE TABLE "SocialProfile" (
 "id" TEXT NOT NULL PRIMARY KEY, "pageId" TEXT NOT NULL, "platform" "SocialPlatform" NOT NULL,
 "username" TEXT, "url" TEXT NOT NULL, "position" INTEGER NOT NULL, "isVisible" BOOLEAN NOT NULL DEFAULT true,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL,
 CONSTRAINT "SocialProfile_position_nonnegative" CHECK ("position" >= 0),
 CONSTRAINT "SocialProfile_pageId_fkey" FOREIGN KEY ("pageId") REFERENCES "Page"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX "SocialProfile_pageId_position_idx" ON "SocialProfile"("pageId","position");

